window.ProjectCharter=(()=>{
 const icon=name=>`<span class="fa-solid fa-${name}" aria-hidden="true"></span>`;
 const lines=value=>String(value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
 const list=value=>lines(value).length?`<ul>${lines(value).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="pc-empty">Not defined yet.</p>';
 function render({project,members,tasks,avatar},record,saved){
  const c=record||{},manager=members.find(m=>m.id===project.managerId),owner=members.find(m=>m.id===c.owner);
  const people=[...new Set([project.managerId,c.owner,...(project.memberIds||[])].filter(Boolean))].map(id=>members.find(m=>m.id===id)).filter(Boolean);
  const section=(id,title,glyph,body)=>`<section id="pc-${id}" class="pc-section"><h3>${icon(glyph)}${title}</h3>${body}</section>`;
  return `<section class="pc-charter"><div class="pc-heading"><div><h2>${icon('file-contract')} Project Charter</h2><p>${esc(c.name||project.name)} <span class="badge">${esc(c.status||'Not created')}</span> <span class="badge">Revision ${saved.version}</span></p></div><div class="work-actions"><button class="secondary" data-pt-reload>${icon('rotate-right')} Reload</button><button class="secondary" data-pc-print>${icon('file-pdf')} Print / Save PDF</button><button class="primary" data-pt-add>${icon('pen')} ${record?'Edit charter':'Create charter'}</button></div></div><p class="pt-feedback" role="status"></p><div class="pc-layout"><div class="pc-content">${section('purpose','1. Project Purpose','bullseye',`<div class="pc-box">${esc(project.description||'Add a project description to define its purpose.')}</div><button class="text-btn pc-edit-purpose" data-project-edit="${esc(project.id)}">Edit project purpose</button>`)}${section('objectives','2. Objectives & Success Criteria','flag',`<div class="pc-box">${list(c.objectives)}</div>`)}${section('scope','3. Scope','list-check',`<div class="pc-scope"><div class="pc-box"><h4>${icon('circle-check')} In Scope</h4>${list(c.scope)}</div><div class="pc-box"><h4>${icon('circle-xmark')} Out of Scope</h4>${list(c.exclusions)}</div></div>`)}${section('deliverables','4. Deliverables','cube',`<div class="bug-table-wrap"><table class="pc-table"><thead><tr><th>#</th><th>Agreed Deliverable</th></tr></thead><tbody>${lines(c.deliverables).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x)}</td></tr>`).join('')||'<tr><td colspan="2">No deliverables defined. Edit the charter and enter one per line.</td></tr>'}</tbody></table></div>`)}${section('constraints','5. Constraints & Assumptions','triangle-exclamation',`<div class="pc-box">${list(c.constraints)}</div>`)}${section('approval','6. Approval','stamp',`<div class="pc-box"><p><b>Status:</b> ${esc(c.status||'Not created')}</p><p>${esc(c.approval||'No approval notes recorded.')}</p></div>`)}</div><div class="pc-side"><section class="pc-card"><h3>${icon('circle-info')} Project Information</h3><dl>${[['Project Name',esc(project.name)],['Project Manager',manager?avatar(manager)+' '+esc(manager.name):'Unassigned'],['Start Date',esc(project.startDate||'—')],['End Date',esc(project.endDate||'—')],['Project Status',esc(project.status||'—')],['Charter Owner',owner?avatar(owner)+' '+esc(owner.name):'Unassigned'],['Last Saved',saved.updatedAt?esc(new Date(saved.updatedAt).toLocaleString()):'Not saved']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></section><section class="pc-card"><h3>${icon('users')} Key Stakeholders</h3><p class="pc-sponsor"><b>Sponsor / Stakeholder</b><br>${esc(c.sponsor||'Not specified')}</p>${people.map(m=>`<div class="pc-person">${avatar(m)}<div><b>${esc(m.name)}</b><small>${esc(m.id===project.managerId?'Project Manager':m.id===c.owner?'Charter Owner':m.role||'Project Member')}</small></div></div>`).join('')||'<p>No members assigned.</p>'}</section><section class="pc-card"><h3>${icon('link')} Project Links</h3><button class="text-btn" data-project-plan="${esc(project.id)}">Tasks / Work Breakdown →</button><button class="text-btn" data-project-gantt="${esc(project.id)}">Schedule & Milestones →</button><button class="text-btn" data-pt-section="risks">Risk Register →</button><button class="text-btn" data-project-docs="${esc(project.id)}">Project Documents →</button></section></div></div></section>`;
 }
 return {render,lines};
})();
